void Solver::restart() {
    fast_lbd_sum = lbd_queue_size = lbd_queue_pos = 0;
    backtrack(0);
    // More aggressive rephasing strategy
    int phase_rand = rand() % 100;
    if (phase_rand < 70) {
        // 70% chance: use local best assignment
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if (phase_rand < 80) {
        // 10% chance: invert local best assignment
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (phase_rand < 90) {
        // 10% chance: random assignment
        for (int i = 1; i <= vars; i++) saved[i] = (rand() % 2) ? 1 : -1;
    } else {
        // 10% chance: reset to saved phases
        // (saved already contains previous phases from backtrack)
    }
}
